{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure compliance with data protection regulations such as GDPR when handling student attendance data.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall allow asynchronous updates for attendance data with a maximum update time of 3 seconds and ensure all updates are logged.",
      "quality_axes": ["Safety|Efficiency|Trustworthiness|Responsibility"],
      "derived_from": ["EFF-06", "RES-02", "SAF-02"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-03",
      "text": "The system shall ensure that all student attendance data is encrypted at rest and in transit.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-04",
      "text": "The system shall implement role-based access control to restrict data access based on user roles while ensuring transparency.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["TRU-02", "RES-02"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-05",
      "text": "The system shall provide real-time data synchronization for accurate attendance records while optimizing resource utilization.",
      "quality_axes": ["Efficiency|Safety"],
      "derived_from": ["SAF-02", "EFF-01"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-06",
      "text": "The system shall maintain an audit log of all access and modifications to attendance records.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["TRU-03"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-07",
      "text": "The system shall allow students to view their attendance records only after successful authentication.",
      "quality_axes": ["Trustworthiness|Safety"],
      "derived_from": ["TRU-04"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-08",
      "text": "The system shall notify students of their attendance status via email or app notification within 24 hours of a class.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-05"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-09",
      "text": "The system shall implement automated alerts for discrepancies in attendance reporting.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-03"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-10",
      "text": "The system shall maintain historical attendance data for at least five years to comply with educational regulations.",
      "quality_axes": ["Responsibility|Efficiency"],
      "derived_from": ["RES-07", "SAF-04", "EFF-04"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-11",
      "text": "The system shall allow students to dispute attendance records through a formal process.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-03"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-12",
      "text": "The system shall undergo regular security audits to identify and mitigate potential vulnerabilities.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-07"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-13",
      "text": "The system shall store historical attendance data for a minimum of five academic years to support long-term analysis.",
      "quality_axes": ["Responsibility|Efficiency"],
      "derived_from": ["SAF-04"],
      "kaos_level": "operational",
      "parent": "F-01"
    }
  ],
  "conflict_resolutions": [
    {
      "ids": ["SAF-06", "RES-02"],
      "outcome": "favored",
      "favored_agent": "ResponsibilityAgent",
      "rationale": "Transparency must be maintained through mandatory logging despite manual overrides."
    },
    {
      "ids": ["TRU-02", "RES-02"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Role-based access control and transparency are integrated to support accountability."
    },
    {
      "ids": ["EFF-06", "GRN-01"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Asynchronous updates are combined with energy-efficient protocols."
    },
    {
      "ids": ["SAF-02", "GRN-01"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Real-time synchronization and energy efficiency are balanced in the final requirements."
    }
  ],
