    },
    {
      "id": "GRN-03",
      "reason": "Low-energy communication is integrated into the asynchronous update strategy."
    },
    {
      "id": "GRN-04",
      "reason": "Report generation formats are implied within the efficiency requirements."
    },
    {
      "id": "GRN-05",
      "reason": "Carbon footprint notifications are not included in the final requirements."
    },
    {
